import requests, re
base='https://screen.wenglab.org'
r=requests.get(base+'/search?assembly=GRCh38&accessions=EH38E1957012', timeout=60)
urls=set(re.findall(r'src=\"(["'^"]+'"\\.js["'^"]*)"'"', r.text))
print(len(urls))
for u in urls:
    full=u if u.startswith('http') else base+u
    try:
        js=requests.get(full, timeout=60).text
    except Exception as e:
        print('err',full,e); continue
    hits=[]
    for pat in ['/api/','accessions','Proximal enhancer','cCRE_class','proximal enhancer','pELS','DNase_maxZ','EH38E']:
        if pat in js:
            hits.append(pat)
    if hits:
        print('\\nCHUNK',u,'hits',hits,'len',len(js))
        for pat in hits:
            idx=js.find(pat)
            print('---',pat,'---')
            print(js[max(0,idx-300):idx+800])
PY"
